-- ES/DE/FR translations for all 5 France milestones.
-- INSERT OR IGNORE, safe against existing English rows.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-b2g-chorus', 'es', 'Facturación electrónica B2G obligatoria a través de Chorus Pro', 'Todos los proveedores de entidades del sector público francés han estado obligados a presentar facturas electrónicamente a través de Chorus Pro desde 2020, antes de la reforma B2B, mucho más amplia.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-b2g-chorus', 'de', 'B2G-E-Rechnungsstellung über Chorus Pro verpflichtend', 'Alle Lieferanten französischer öffentlicher Stellen müssen seit 2020 Rechnungen elektronisch über Chorus Pro einreichen, noch vor der weitaus größeren B2B-Reform.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-b2g-chorus', 'fr', 'Facturation électronique B2G obligatoire via Chorus Pro', 'Tous les fournisseurs d''entités du secteur public français doivent soumettre leurs factures électroniquement via Chorus Pro depuis 2020, bien avant la réforme B2B, beaucoup plus vaste.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-pa-critical-mass', 'es', 'La red de acreditación de plataformas alcanza una masa crítica', 'Más de 100 Plateformes Agréées (PA) habían recibido la acreditación de la DGFiP en este punto, dando a las empresas una auténtica variedad de proveedores certificados antes de la puesta en marcha de septiembre.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-pa-critical-mass', 'de', 'Netzwerk akkreditierter Plattformen erreicht kritische Masse', 'Zu diesem Zeitpunkt hatten über 100 Plateformes Agréées (PA) die DGFiP-Akkreditierung erhalten, was Unternehmen vor dem Start im September eine echte Auswahl an zertifizierten Anbietern gab.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-pa-critical-mass', 'fr', 'Le réseau de plateformes agréées atteint une masse critique', 'Plus de 100 Plateformes Agréées (PA) avaient reçu l''accréditation de la DGFiP à ce stade, offrant aux entreprises un véritable choix de prestataire certifié avant le lancement de septembre.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-finance-law-2026', 'es', 'La Ley de Finanzas renombra formalmente PDP a PA y aclara las sanciones', 'El artículo 123 de la Ley de Finanzas para 2026 (Ley n.º 2026-103) renombró la "Plateforme de Dématérialisation Partenaire (PDP)" como "Plateforme Agréée (PA)" y modificó los artículos 289 bis, 289 E, 290, 1737 y 1788 D del CGI para establecer sanciones más claras y elevadas por incumplimiento.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-finance-law-2026', 'de', 'Finanzgesetz benennt PDP formell in PA um und präzisiert Sanktionen', 'Artikel 123 des Finanzgesetzes 2026 (Gesetz Nr. 2026-103) benannte die "Plateforme de Dématérialisation Partenaire (PDP)" in "Plateforme Agréée (PA)" um und änderte die Artikel 289 bis, 289 E, 290, 1737 und 1788 D des CGI, um klarere, höhere Sanktionen bei Nichteinhaltung festzulegen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-finance-law-2026', 'fr', 'La loi de finances renomme formellement les PDP en PA et clarifie les sanctions', 'L''article 123 de la loi de finances pour 2026 (loi n° 2026-103) a renommé la « Plateforme de Dématérialisation Partenaire (PDP) » en « Plateforme Agréée (PA) » et a modifié les articles 289 bis, 289 E, 290, 1737 et 1788 D du CGI pour fixer des sanctions plus claires et plus élevées en cas de non-conformité.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'es', 'Mandato de recepción + emisión para grandes y medianas empresas', 'Todas las empresas registradas a efectos de IVA en Francia deben poder recibir facturas electrónicas; las grandes y medianas empresas también deben emitirlas a través del portal público (PPF) o de una plataforma acreditada (PA, antes PDP).', '["Registre la entrada de su empresa en el directorio de la PPF (Portail Public de Facturation)", "Elija una Plateforme Agréée acreditada o use el portal público gratuito", "Configure el e-reporting para transacciones B2C y transfronterizas junto con la facturación electrónica"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'de', 'Empfangspflicht + Ausstellung für große und mittlere Unternehmen', 'Alle umsatzsteuerpflichtigen Unternehmen in Frankreich müssen in der Lage sein, E-Rechnungen zu empfangen; große und mittlere Unternehmen müssen sie zudem über das öffentliche Portal (PPF) oder eine akkreditierte Plattform (PA, ehemals PDP) ausstellen.', '["Registrieren Sie den Verzeichniseintrag Ihres Unternehmens bei der PPF (Portail Public de Facturation)", "Wählen Sie eine akkreditierte Plateforme Agréée oder nutzen Sie das kostenlose öffentliche Portal", "Richten Sie das E-Reporting für B2C- und grenzüberschreitende Transaktionen zusätzlich zur E-Rechnungsstellung ein"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'fr', 'Obligation de réception + émission pour les grandes et moyennes entreprises', 'Toutes les entreprises assujetties à la TVA en France doivent pouvoir recevoir des factures électroniques ; les grandes et moyennes entreprises doivent également les émettre via le portail public (PPF) ou une plateforme accréditée (PA, anciennement PDP).', '["Enregistrez l''entrée de votre entreprise dans l''annuaire de la PPF (Portail Public de Facturation)", "Choisissez une Plateforme Agréée accréditée ou utilisez le portail public gratuit", "Mettez en place l''e-reporting pour les transactions B2C et transfrontalières en parallèle de la facturation électronique"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'es', 'El mandato de emisión se extiende a todas las empresas restantes', 'Las pequeñas y microempresas, incluidos los autónomos, deben emitir facturas electrónicas, completando la reforma francesa de facturación electrónica y e-reporting B2B por fases.', '["Finalice la integración con el software de facturación o la PA con suficiente antelación al plazo", "Confirme que su software es compatible con los formatos Factur-X, UBL o CII"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'de', 'Ausstellungspflicht erstreckt sich auf alle verbleibenden Unternehmen', 'Klein- und Kleinstunternehmen, einschließlich Freiberuflern, müssen E-Rechnungen ausstellen, womit Frankreichs stufenweise B2B-E-Invoicing- und E-Reporting-Reform abgeschlossen wird.', '["Schließen Sie die Integration mit der Rechnungssoftware oder PA rechtzeitig vor der Frist ab", "Bestätigen Sie, dass Ihre Software Factur-X-, UBL- oder CII-Format unterstützt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'fr', 'L''obligation d''émission s''étend à toutes les entreprises restantes', 'Les petites et micro-entreprises, y compris les indépendants, doivent émettre des factures électroniques, achevant la réforme française de facturation électronique et d''e-reporting B2B par phases.', '["Finalisez l''intégration avec le logiciel de facturation ou la PA bien avant l''échéance", "Confirmez que votre logiciel prend en charge le format Factur-X, UBL ou CII"]');
